package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Populates the response-only {@link Owner#isPossibleDuplicate() possibleDuplicate} and
 * {@link Owner#getPossibleDuplicateOf() possibleDuplicateOf} fields from the shared
 * {@link PossibleDuplicate} rule: true, with the matching owner id, when this owner shares an
 * existing owner's last name and postcode with a different telephone; otherwise false with no
 * id. Mutates the loaded owner in place so the responder's mapper carries the flag onto the DTO.
 *
 * <p>A declared household member — an owner whose {@code householdId} is shared by another
 * owner, only possible when it was created with {@code sharesHousehold} — is never a suspected
 * duplicate, so its flag is forced false regardless of the soft match.
 */
public class FlagPossibleDuplicate {

    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
        if (isDeclaredHouseholdMember(owner, ownerRepository)) {
            owner.setPossibleDuplicate(false);
            owner.setPossibleDuplicateOf(null);
            return;
        }
        Integer match = PossibleDuplicate.matchOf(owner, ownerRepository);
        owner.setPossibleDuplicate(match != null);
        owner.setPossibleDuplicateOf(match);
    }

    /**
     * Whether another owner already carries this owner's (non-blank) householdId. Because the
     * duplicate gate rejects an undeclared second owner in a household, a shared householdId
     * means this owner is a declared member.
     */
    private static boolean isDeclaredHouseholdMember(Owner owner, OwnerRepository ownerRepository) {
        String householdId = owner.getHouseholdId();
        if (householdId == null || householdId.isBlank()) {
            return false;
        }
        for (Owner existing : ownerRepository.findAll()) {
            if (owner.getId() != null && owner.getId().equals(existing.getId())) {
                continue;
            }
            if (householdId.equals(existing.getHouseholdId())) {
                return true;
            }
        }
        return false;
    }
}

package org.springframework.samples.petclinic.rest.function.owner;

import org.springframework.samples.petclinic.model.Owner;

/**
 * Single source of truth for an owner's duplicate-detection identity key, shared by the
 * owner-create pipeline. The key consolidates the former separate telephone, email and
 * household duplicate checks into one derived value so two owners conflict only when their
 * whole keys are equal.
 *
 * <p>The key is {@code normalizedTelephone + "|" + (email or "") + "|" + (householdId or "")}.
 * Because the telephone is part of the key, two members of the same household (same
 * {@code householdId}) with different telephones derive different keys and are both allowed;
 * only an exact full-key match is a duplicate.
 */
public final class OwnerIdentity {

    private OwnerIdentity() {
    }

    /**
     * Build the identity key from already-normalized parts: a normalized E.164 telephone, a
     * lower-cased email (or {@code null}) and a household id (or {@code null}). A {@code null}
     * segment is rendered as empty.
     */
    static String key(String normalizedTelephone, String email, String householdId) {
        return orEmpty(normalizedTelephone) + "|" + orEmpty(email) + "|" + orEmpty(householdId);
    }

    /**
     * The identity key of an owner, re-deriving the normalized telephone and email from the
     * stored values so it compares identically to a freshly built key and can be derived at the
     * Owner-to-DTO boundary for any response.
     */
    public static String of(Owner owner) {
        return key(OwnerTelephone.normalize(owner.getTelephone()),
                OwnerEmail.normalize(owner.getEmail()), owner.getHouseholdId());
    }

    private static String orEmpty(String value) {
        return value == null ? "" : value;
    }
}
